<script>
 import {onMount} from 'svelte'; import {goto} from '$app/navigation'; import {ShieldCheck,Stethoscope,UserRound,Handshake,Eye,EyeOff} from 'lucide-svelte'; import {supabase,api} from '$lib/auth.js'; import {ROLE_PATH} from '$lib/config.js';
 const PORTALS=[{role:'administrator',name:'ADMIN',label:'Administrator',email:'admin.demo@kakang.test',icon:ShieldCheck},{role:'therapist',name:'TERAPIS',label:'Terapis',email:'terapis.demo@kakang.test',icon:Stethoscope},{role:'customer',name:'CUSTOMER',label:'Customer',email:'customer.demo@kakang.test',icon:UserRound},{role:'referral',name:'REFERRAL',label:'Referral',email:'referral.demo@kakang.test',icon:Handshake}];
 let selected=PORTALS[0],pin='',busy=false,failure='',showPin=false;
 onMount(checkSession);
 async function checkSession(){try{const {data:{session}}=await supabase.auth.getSession();if(session){const {profile}=await api('/me');await goto(ROLE_PATH[profile.role],{replaceState:true});}}catch{await supabase.auth.signOut();}}
 async function submit(){if(!/^\d{6}$/.test(pin)){failure='Masukkan PIN tepat 6 angka.';return;}busy=true;failure='';try{const {error}=await supabase.auth.signInWithPassword({email:selected.email,password:pin});if(error)throw error;await checkSession();}catch(e){failure=e.message?.includes('Invalid login')?'PIN salah. Periksa kembali PIN '+selected.label+'.':e.message||'Login belum berhasil.';}finally{busy=false;}}
 function choose(portal){selected=portal;pin='';failure='';}
</script>
<svelte:head><title>Masuk — HEIJO Reflexology</title></svelte:head>
<div class="auth-shell"><section class="brand-panel"><a class="brand" href="/" aria-label="HEIJO Reflexology"></a><div class="intro"><span>HEIJO REFLEXOLOGY</span><h1>Saatnya<br/>melepas lelah.</h1><p>Masuk ke portal sesuai akun Anda untuk mengelola layanan, reservasi, dan pendapatan.</p></div><p class="motto">REFLEKSI · RELAKSASI · HIJAMAH</p></section><main><div class="login-box"><span class="eyebrow">SELAMAT DATANG</span><h2>Masuk {selected.label}</h2><p class="description">Masukkan PIN 6 angka untuk membuka akun {selected.label}.</p><div class="role-picker">{#each PORTALS as portal}<button class:active={selected.role===portal.role} onclick={()=>choose(portal)}><svelte:component this={portal.icon} size={19}/><span>{portal.name}</span></button>{/each}</div>{#if failure}<div class="message">{failure}</div>{/if}<form onsubmit={e=>{e.preventDefault();submit();}}><label>PIN 6 angka<div class="password"><input required inputmode="numeric" maxlength="6" autocomplete="current-password" type={showPin?'text':'password'} bind:value={pin} placeholder="••••••"/><button type="button" onclick={()=>showPin=!showPin}>{#if showPin}<EyeOff size={19}/>{:else}<Eye size={19}/>{/if}</button></div></label><button class="submit" disabled={busy}>{busy?'Memeriksa…':'Masuk sebagai '+selected.label}</button></form><p class="access-note"><ShieldCheck size={16}/>PIN setiap akun dapat diubah oleh Admin dari menu Kelola Akun.</p></div><small>© 2026 HEIJO Reflexology</small></main></div>
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;font-family:Arial,Helvetica,sans-serif;background:#f8f5ef;color:#083d2b}:global(button),:global(input){font:inherit}:global(button){cursor:pointer}.auth-shell{min-height:100vh;display:grid;grid-template-columns:1fr 1fr}.brand-panel{padding:48px 64px;background:radial-gradient(ellipse at 100% 100%,#c8a45344,transparent 55%),#004326;color:#fff;display:flex;flex-direction:column;border-right:3px solid #c8a453}.brand{display:block;width:185px;height:57px;background:#004326 url('/heijo-gold.jpg') center/220% auto no-repeat}.intro{margin:auto 0}.intro>span,.eyebrow{font-size:11px;letter-spacing:2px;font-weight:800;color:#f0ce79}.intro h1{font-size:55px;line-height:1.05;letter-spacing:-2px;margin:20px 0}.intro p{line-height:1.8;color:#ddede2;max-width:420px}.motto{font-size:11px;letter-spacing:1.4px;color:#f1d486;font-weight:700}.login-box{width:min(430px,100%)}main{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:42px}.eyebrow{color:#87641e}h2{font-size:32px;margin:15px 0 8px}.description{color:#426451;line-height:1.6;margin:0 0 25px}.role-picker{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:24px}.role-picker button{min-height:57px;border-radius:12px;border:1px solid #ccb66f;background:#00543b;color:#f5cf72;display:flex;gap:9px;align-items:center;justify-content:center;font-size:12px;font-weight:800}.role-picker button:not(.active){background:#fffdf8;color:#07523a;border-color:#d7ddd3}.message{padding:12px 14px;background:#ffede5;color:#8a2c18;border-radius:10px;font-size:13px;margin-bottom:18px}form{display:grid;gap:17px}label{display:grid;gap:9px;font-size:14px;font-weight:800}.password{position:relative}.password input{width:100%;padding:15px 52px 15px 15px;border:1px solid #b9cfc1;border-radius:10px;font-size:20px;letter-spacing:8px;color:#063e2c}.password button{position:absolute;right:13px;top:14px;border:0;background:none;color:#27624a}.submit{border:1px solid #c5a353;border-radius:11px;padding:15px;background:linear-gradient(115deg,#006346,#003d2a);color:#fff;font-weight:800}.access-note{font-size:12px;line-height:1.7;color:#547360;margin-top:26px;border-top:1px solid #ddd7c7;padding-top:20px}.access-note :global(svg){vertical-align:middle;margin-right:6px}main small{margin-top:40px;color:#5d7768}@media(max-width:700px){.auth-shell{grid-template-columns:1fr}.brand-panel{padding:27px;border-right:0;border-bottom:3px solid #c8a453}.intro{margin:28px 0 0}.intro h1{font-size:37px}.intro h1 br{display:none}.motto{display:none}main{padding:34px 22px}.login-box{max-width:460px}}
</style>
